const SHAKE = {{shake}}, SPRING = {{spring}};
let hit = 0, y = 0, vy = 0;
addEventListener('click', () => { hit = 1; vy = -6; });
function frame() {
  hit *= 0.9;
  vy += (0 - y) * (SPRING / 100) - vy * 0.12;
  y += vy;
  const sx = (Math.random() - 0.5) * SHAKE * hit;
  const sy = (Math.random() - 0.5) * SHAKE * hit;
  ctx.clearRect(0, 0, W(), H());
  ctx.save(); ctx.translate(sx, sy);
  ctx.fillStyle = '#f59e0b';
  ctx.fillRect(W() / 2 - 30, H() / 2 - 20 + y * 4, 60, 40);
  ctx.restore();
  ctx.fillStyle = '#eee'; ctx.font = '13px system-ui';
  ctx.fillText('화면을 눌러 보라', 16, 22);
  requestAnimationFrame(frame);
}
frame();

async function hitStop(sec = 0.05) {
  timeScale = 0;
  await wait(sec);       // 실제 시간 기준으로 기다린다
  timeScale = 1;
}

const easeOutQuad = (t) => 1 - (1 - t) * (1 - t);
const easeOutBack = (t) => 1 + 2.70158 * Math.pow(t - 1, 3) + 1.70158 * Math.pow(t - 1, 2);
